{
  "schemaVersion": "0.2",
  "slug": "switch",
  "name": "Switch",
  "status": "experimental",
  "purpose": "Toggles a setting on or off with a sliding control.",
  "scenarios": [
    "Enable dark mode",
    "Turn notifications on or off",
    "Activate airplane mode"
  ],
  "props": {
    "checked": {
      "type": "boolean",
      "required": true,
      "description": "Controlled checked state."
    },
    "onChange": {
      "type": "event",
      "required": true,
      "description": "Receives the next checked state."
    },
    "label": {
      "type": "string",
      "required": true,
      "description": "Visible and accessible label for the switch."
    },
    "disabled": {
      "type": "boolean",
      "required": false,
      "description": "Prevents toggling the switch.",
      "default": false
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Unchecked and enabled."
    },
    {
      "name": "checked",
      "description": "Checked and enabled."
    },
    {
      "name": "disabled",
      "description": "Cannot be toggled."
    }
  ],
  "composition": {
    "allowedParents": [
      "form",
      "dialog",
      "field-group"
    ],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use a switch for actions that require a confirmation step; use a button.",
    "Do not remove the visible label."
  ],
  "a11y": {
    "role": "switch",
    "keyboard": [
      "Tab focuses",
      "Space toggles"
    ],
    "focus": "Visible focus indicator on the control.",
    "labeling": "Visible label is associated with the hidden checkbox.",
    "wcag": [
      "1.3.1",
      "2.1.1",
      "4.1.2"
    ]
  },
  "responsive": {
    "strategy": "The control keeps a fixed width; the label wraps on narrow screens.",
    "breakpoints": {
      "compact": "Touch target stays at least 44px; label wraps.",
      "medium": "Inline layout remains comfortable.",
      "large": "Inline layout remains comfortable."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. The thumb uses logical transforms; direction inherits from document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "switch",
    "states": [
      "default",
      "checked",
      "disabled"
    ],
    "intents": [
      "toggle-setting"
    ]
  }
}

.cu-switch {
  display: inline-flex;
  align-items: center;
  gap: var(--cu-space-2);
  cursor: pointer;
  min-block-size: 2.25rem;
}

.cu-switch__control {
  position: relative;
  inline-size: 2.75rem;
  block-size: 1.5rem;
  border-radius: 9999px;
  background: var(--cu-color-border-default);
  flex: none;
  transition: background-color 140ms ease;
}

.cu-switch[data-state='checked'] .cu-switch__control {
  background: var(--cu-color-palette-brand);
}

.cu-switch__thumb {
  position: absolute;
  inset-block: 0.125rem;
  inset-inline-start: 0.125rem;
  inline-size: 1.25rem;
  block-size: 1.25rem;
  border-radius: 50%;
  background: var(--cu-color-background-default);
  transition: transform 140ms ease;
  transform: translateX(0);
}

.cu-switch[data-state='checked'] .cu-switch__thumb {
  transform: translateX(1.25rem);
}

.cu-switch__label {
  color: var(--cu-color-fg-default);
  font-size: 0.9375rem;
  user-select: none;
}

.cu-switch:disabled,
.cu-switch[data-disabled] {
  cursor: not-allowed;
  opacity: 0.55;
}

.cu-switch__control:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
  outline-offset: 3px;
}

@media (prefers-reduced-motion: reduce) {
  .cu-switch__control,
  .cu-switch__thumb {
    transition-duration: 0.01ms;
  }
}

import { SwitchPrimitive } from '@chameleon-ui/primitives'
import './styles.css'

export interface SwitchProps {
  checked: boolean
  onChange: (checked: boolean) => void
  label: string
  disabled?: boolean
  className?: string
}

export function Switch({ checked, onChange, label, disabled = false, className }: SwitchProps) {
  const classes = ['cu-switch', className].filter(Boolean).join(' ')

  return (
    <SwitchPrimitive.Root
      checked={checked}
      className={classes}
      data-ai-role="switch" data-ai-intent="toggle-setting"
      data-ai-state={checked ? 'checked' : disabled ? 'disabled' : 'default'}
      disabled={disabled}
      onCheckedChange={(details) => onChange(!!details.checked)}
    >
      <SwitchPrimitive.Label className="cu-switch__label">{label}</SwitchPrimitive.Label>
      <SwitchPrimitive.Control className="cu-switch__control">
        <SwitchPrimitive.Thumb className="cu-switch__thumb" />
      </SwitchPrimitive.Control>
      <SwitchPrimitive.HiddenInput />
    </SwitchPrimitive.Root>
  )
}
